import{_ as p}from"./chunks/CityLink.vue_vue_type_script_setup_true_lang.DYs3D5sh.js";import{o as a,c as r,j as i,a as l,F as o,B as m,b as c,a5 as n}from"./chunks/framework.CnBNXlt7.js";import"./chunks/travelogue.BgrUIWBQ.js";import"./chunks/utils.Crj2JTAd.js";import"./chunks/dayjs.min.DTWwpTri.js";const d="/life/img/trip/log20250503-01.png",g="/life/img/trip/log20250503-02.png",u="/life/img/trip/log20250503-03.png",_="/life/img/trip/log20250503-04.png",b="/life/img/trip/log20250503-05.png",k="/life/img/trip/log20250503-06.png",A=JSON.parse('{"title":"景德镇","description":"","frontmatter":{"city":["景德镇"],"date":"2025/05/03"},"headers":[],"relativePath":"trip/travelogue/20250503.md","filePath":"trip/travelogue/20250503.md","lastUpdated":1752763073000}'),h={name:"trip/travelogue/20250503.md"},B=Object.assign(h,{setup(f){return(s,t)=>(a(),r("div",null,[t[0]||(t[0]=i("h1",{id:"景德镇",tabindex:"-1"},[l("景德镇 "),i("a",{class:"header-anchor",href:"#景德镇","aria-label":'Permalink to "景德镇"'},"​")],-1)),(a(!0),r(o,null,m(s.$frontmatter.city,(e,y)=>(a(),c(p,{city:e,date:new Date(s.$frontmatter.date)},null,8,["city","date"]))),256)),t[1]||(t[1]=n('<h2 id="_2025-05-03" tabindex="-1">2025/05/03 <a class="header-anchor" href="#_2025-05-03" aria-label="Permalink to &quot;2025/05/03&quot;">​</a></h2><p>周六</p><div class="tip custom-block"><p class="custom-block-title">计划</p><p>到酒店放行李，抚州弄，兔子家小炒<br> 陶阳里历史文化街区，需要门票<br> 御窑博物馆，提前3天预约，5.1预约<br> 而后前往陶溪川文创街区</p></div><p>16:32抵达景德镇北站，北广场公交站12/912路，前往火车站，预计17:30抵达酒店。实际17:10抵达酒店，高铁出站直接去北广场，去完卫生间，就看到12路，刚上车即发车。一共就4个人，全程几乎没有停站，没人坐，1块钱的公交车，没有空调，30度的高温，在停车等灯时格外的炎热。</p><details class="details custom-block"><summary>17:24-19:17，5.13km</summary><p><img src="'+d+'" alt="img"></p></details><p>抵达后先前往酒店，放置行李。正好听到有人问老板本地菜推荐，说有“<strong>回家吃饭</strong>”“<strong>图味美小黄鱼</strong>”。果不其然，出酒店西走50米，就看到小黄鱼门口坐满了排队的人，再走几十米，回家吃饭也是如此，便取了号。暂时不饿，先前往抚州弄，而后再回来吃亦可。顺路说不定可以遇到其他家的回家吃饭。</p><p>路上看到一个煎包子铺，还以为是特色，2块一个，韭菜粉条包，就是加了很多小米辣。也算是开开江西胃了。</p><p>抚州弄，实际就是小吃街，并且是非常小的小吃街。没什么可买的，买了俩甜筒。走出抚州弄，果然，再次看到<strong>回家吃饭</strong>，上去看了看，不让取号了。找找看<strong>兔子家小炒</strong>，先点菜付款后等上菜，说是一份一份炒，很慢，提醒预计等待两个小时，就放弃了。先逛逛吧，马路对面硕大的<strong>御窑厂</strong>，入口还写着明清各个皇帝的年号。原来这就是陶阳里啊。还是老样子，先去游客中心取地图。</p><p>买好门票53块，直接进入。按地图地毯式探索。慢慢地，饭号快到了，肯定是赶不上了，姑且继续探索吧。里面的御窑博物馆说是需要预约，实则完全没有检票的，随便进。</p><p>出来时，已然过号，想到之前群友推荐的赣菜，搜了一下，不错，竟然有一个店老三样，就在回程附近。还可以线上取号，简直完美。</p><details class="details custom-block"><summary>菜单</summary><p><img src="'+g+'" alt="img"></p></details><p>黄喉很棒，牛肉不推荐，皮蛋没有尝到皮蛋，不太懂。</p><p>吃完休息片刻，看了看陶溪川有点远，便直接回去了。</p><h2 id="_5-4-周日" tabindex="-1">5.4 周日 <a class="header-anchor" href="#_5-4-周日" aria-label="Permalink to &quot;5.4 周日&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">计划</p><p>早饭后，陶瓷博物馆，预计2h<br> 中国陶瓷博物馆，提前7天，4.28预约，预约失败，等现场看看。<br> 而后前往县汽车站，坐车前往瑶里古镇，1.5h公交车，6元。<br> 瑶里末班车17:00</p></div><p>早上9:50抵达牛骨粉店，品鉴一下这里的牛骨如何。拌粉不错，牛骨不行，肉不够软糯，嘬不下来，非常难啃的骨头，一般般。原想公交车去陶瓷博物馆，等了几分钟，站台其他经停公交车都见过，唯独没见到“陶博城专线二”，高德地图显示“临时停运”，莫非真的停运。打车去吧，一看10块钱，5km，相当便宜。 中国陶瓷博物馆，现场也失败，直接不让约，让哪来的回哪去。而并且，分时段预约，让大伙全部站在分时段的大棚下，不让进，不知道等待什么呢？很抽象，立即溜。</p><p>打车直接去县汽车站吧。11:31抵达，以为赶不上公交车了。正好进去就喊“去瑶里的快上车”，上车扫码6元/人。33分，人上的差不多即开出。预计1.5h车程。 11:52路过瓷宫，外面很多人，在车上拍了照片。 12:19抵达鹅湖站。全程基本65码。县汽车站-瑶里，车程48km。 12:45左右抵达。照例，游客中心取地图，哈，地图空了，很多零星景点门票出售，提前看过，一个都不要买，古镇没有大门，随便逛。路边地图牌子挺多，指示牌有些凌乱，倒也能参考一二。继续扫荡式游玩。不走回头路。</p><details class="details custom-block"><summary>12:50-14:36，2.98km</summary><p><img src="'+u+'" alt="img"></p></details><p>14:11去坐返程，14:33上车，很牛，回程空调开放。14:46发车，15:50抵达，挺快的，一路没怎么停车。下车直接去陶艺，由于临时决定去做陶艺，提前下车，走得急，伞忘记拿了。打车去，20块，10km左右。原来这就是陶溪川呀！ 16:20抵达，但是伞丢了，太可恨了。 今天早上出门，就看了天气，说18:00左右会有雨，便拿了伞，拿了一天，在晚上即将用到的时候丢了，无语。</p><p>16:45决定返程找伞，正好看到一辆反向37路，再等等。16:59上车，17:45到达，可惜汽车站关门了。唉，继续公交回去吧。返程已经开始大雨。</p><p>到时，陶艺还没做完。买了一点肉饼，肉串很便宜，但似乎都是鸡肉，怪不得便宜，不是很好吃。而后又出来吃了一碗粉，饱了，中辣太辣了，紧急吃了一个油条解辣，雨继续下着。</p><p>20:10左右，陶艺做完，去就近吃一个景巷小厨，不推荐，太贵了。血鸭实在太少了，肉非常少。豆角茄条香爆了。</p><details class="details custom-block"><summary>菜单</summary><p><img src="'+_+'" alt="img"></p></details><p>吃完，大雨被困，打车等了半个小时左右吧，直接回酒店了。</p><h2 id="_5-5-周一" tabindex="-1">5.5 周一 <a class="header-anchor" href="#_5-5-周一" aria-label="Permalink to &quot;5.5 周一&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">计划</p><p>古窑民俗博览区，提前15天，4.21预约<br> 已预约，5.5 10:00-11:00<br> 成人85元，学生45元</p></div><p>今天整点不一样的，拌粉+瓦罐汤，也算是特色了。吃完打车前往5A景区，古窑民俗博览区。不愧是5A，票价虽贵，可玩性非常高，景区很大，加上微雨，实在舒服。</p><details class="details custom-block"><summary>10:21-13:04，4.57km</summary><p><img src="'+b+'" alt="img"></p></details><p>游玩结束直接打车回酒店收拾行李，想着继续吃特色，就吃小黄鱼吧，先去取号，而后回酒店收拾行李。此时，回程的票仍然没有候补到，很麻烦。</p><details class="details custom-block"><summary>先去吃饭吧。</summary><p><img src="'+k+'" alt="img"></p></details><p>饭后等公交车，前往高铁站，打算在高铁站抢一个能上车的票，思前想后，看了看租车，也不贵，一天200，鉴于路途遥远，就租好一点的车，迈腾300+保险80，一共380一天。直接公交下车，前往取车。</p><p>详情参考自驾。</p>',32))]))}});export{A as __pageData,B as default};
